PECAS = (20000, 10000, 5000, 2000, 1000, 500, 200, 100, 50, 25, 10, 5, 1)def paraCentavos(texto):    textoLimpo = texto.strip().replace(",",".")    try:        numeroFloat = float(textoLimpo)    except ValueError:        raise ValueError("o valor digitado contem caracteres invalidos")    if numeroFloat < 0:        raise ValueError("o numero nao e permitido")    pecas = textoLimpo.split(".")    if len(pecas) > 1 and len(pecas[1]) > 2:        raise ValueError("o numero nao pode ter mais de duas casas decimais")    centavos = round(numeroFloat * 100)    return centavosdef centavo(valorEmCentavos):    resultado = {}    resto = valorEmCentavos    for peca in PECAS:        if resto == 0:            break        qtd, resto = divmod(resto, peca)        if qtd > 0:            resultado[peca] = qtd    return resultado